using System;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;
namespace Xinghai.MapEditor.Editor {public static class RecoveryProof {
 public static void Interrupt(){try{var doc=new MapDocument{mapId="recovery-proof",cells=new[]{new Cell{x=0,y=0,z=0,color=0}}};MapBaker.Bake(doc,"Assets/Generated/recovery-proof");string file=Directory.GetFiles("Assets/Generated/recovery-proof","Chunk_*.asset")[0].Replace('\\','/');File.WriteAllBytes("../logs/recovery-expected.bin",File.ReadAllBytes(file));File.WriteAllText("../logs/recovery-path.txt",file);var journal=new BakeJournal();journal.Watch(file);var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(file);mesh.colors=Enumerable.Repeat(Color.red,mesh.vertexCount).ToArray();EditorUtility.SetDirty(mesh);AssetDatabase.SaveAssets();Debug.Log("XH_RECOVERY_INTERRUPTED_WITH_JOURNAL");EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
 public static void Verify(){try{BakeJournal.Recover();string file=File.ReadAllText("../logs/recovery-path.txt");if(!File.ReadAllBytes(file).SequenceEqual(File.ReadAllBytes("../logs/recovery-expected.bin")))throw new Exception("Restart did not recover saved mesh");File.WriteAllText("../logs/recovery.json","{\"passed\":true,\"separateEditorProcess\":true}");Debug.Log("XH_RECOVERY_PASS");EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
}}
